globalEvents.onPlayerJoined.add(() => botKick());
globalEvents.onSeatChanged.add(() => botKick());

world.addObjectMenuItem({ id: TBL_MENU_NEW_GAME, label: "New Othello game", match: { kinds: ["board"] } });

globalEvents.onObjectMenuItem.add((object, itemId) => {
  if (itemId !== TBL_MENU_NEW_GAME) return;
