      world.broadcast(who + " forfeits the match.");
      mtcPending = [];
      mtcRecording = false;
      if (!game || gameOver || colour === 0) return;
      gameOver = true;
      tblEndNote = tblColourName(colour) + " forfeits. " + tblColourName(-colour) + " wins.";
      await tblSave();
      tblRenderStatus();
    });
  });

  /** Everyone agreed a draw: the platform records it; the board says so. */
  match.onDrawAgreed.add(() => {
    void tblRun(async () => {
      mtcPending = [];
      mtcRecording = false;
      if (!game || gameOver) return;
      gameOver = true;
      tblEndNote = "Draw agreed.";
      world.broadcast("Draw agreed.");
      await tblSave();
      tblRenderStatus();
    });
