  });

  match.onFinalized.add((info) => {
    world.log("Othello: the match is " + info.status + (info.ranked ? " (ranked)." : " (unranked)."));
  });
}

void tblRun(async () => {
  if (!(await tblEnsureReady())) return;
  world.log("Othello ready.");
  await botDriveSeatedBots();
});

