}
/**
 * Find the 64 squares: snap points labelled a1 ... h8. Failing that, any 64 snap points are
 * read as an 8 x 8 grid (rank 1 at the lowest z, file a at the lowest x) with a warning.
 */
async function tblLoadSquares() {
    const points = await world.getSnapPoints();
    const byCell = [];
    for (let i = 0; i < 64; i += 1)
        byCell.push(null);
    let labelled = 0;
    for (const point of points) {
        const named = /^\s*([a-hA-H])\s*([1-8])\s*$/.exec(point.label);
        if (!named)
            continue;
        const cell = (Number(named[2]) - 1) * 8 + TBL_FILES.indexOf(named[1].toLowerCase());
        if (!byCell[cell]) {
            byCell[cell] = point;
            labelled += 1;
        }
    }
    if (labelled < 64) {
        if (points.length !== 64) {
            world.broadcast("Othello: label the board's 64 snap points a1 to h8 (found " + labelled + " labelled, " + points.length + " in all).");
            return false;
        }
        const sorted = points.slice().sort((p, q) => p.position[2] - q.position[2]);
        for (let rank = 0; rank < 8; rank += 1) {
            const row = sorted.slice(rank * 8, rank * 8 + 8).sort((p, q) => p.position[0] - q.position[0]);
            for (let file = 0; file < 8; file += 1)
                byCell[rank * 8 + file] = row[file];
        }
        world.broadcast("Othello: the snap points are not labelled a1 to h8, so the board was read as a grid. Label them for move names that match the board.");
    }
    const cells = byCell;
    const a1 = cells[0].position;
    const h1 = cells[7].position;
    const a8 = cells[56].position;
    tblSquareSize = Math.max(0.01, tblPlanDistance(a1, h1) / 7);
    tblFileAxis = tblUnit(h1[0] - a1[0], h1[2] - a1[2]);
    tblRankAxis = tblUnit(a8[0] - a1[0], a8[2] - a1[2]);
