    let cy = 0;
    let cz = 0;
    for (const point of cells) {
        cx += point.position[0] / 64;
        cy += point.position[1] / 64;
        cz += point.position[2] / 64;
    }
    tblCentre = [cx, cy, cz];
    tblSquares = cells.map((point, cell) => ({
        cell,
        name: tblSquareName(cell),
        position: [point.position[0], point.position[1], point.position[2]],
        reach: Math.max(point.snapRadius, tblSquareSize * 0.45)
