// ---------------------------------------------------------------- reading the table -
/**
 * Which way up a disc lies, from its rotation (degrees). A disc lying flat shows its model's
 * upper face when its local up axis points up; for a flat piece that is cos(x) * cos(z) > 0
 * whichever way the yaw and the angle order are written.
 */
function tblDiscColour(rotation) {
    const upright = Math.cos((rotation[0] * Math.PI) / 180) * Math.cos((rotation[2] * Math.PI) / 180) >= 0;
    return upright === tblSettings.blackWhenUpright ? 1 : -1;
}
async function tblDiscHandles() {
    const tag = tblSettings.discTag.trim();
    return tag.length > 0 ? world.getAllObjects({ kind: "token", tag }) : world.getAllObjects({ kind: "token" });
}
async function tblRead() {
    const handles = await tblDiscHandles();
    const cells = [];
    const byCell = [];
    for (let i = 0; i < 64; i += 1) {
        cells.push(0);
        byCell.push(null);
    }
    const discs = [];
    const crowded = [];
    for (const handle of handles) {
        const disc = { handle, colour: tblDiscColour(handle.rotation), cell: tblCellAt(handle.position) };
        discs.push(disc);
        if (disc.cell < 0) {
            tblHomes.set(handle.id, [handle.position[0], handle.position[1], handle.position[2]]);
            continue;
        }
        if (byCell[disc.cell]) {
            if (crowded.indexOf(disc.cell) < 0)
                crowded.push(disc.cell);
            continue;
        }
        byCell[disc.cell] = disc;
        cells[disc.cell] = disc.colour;
