}
// ---------------------------------------------------------------- seats --------------
function tblSeatIsBot(seat) {
    if (!seat)
        return false;
    return world.getPlayers().some((player) => player.seat === seat && player.isBot);
}
function tblColourIsBot(colour) {
    return tblSeatIsBot(gameSeatOf[tblColourKey(colour)]);
}
/**
 * The seat a person plays from. A person with no seat (everyone on a solo table, where nobody
