function tblSeatOfPeer(peerId) {
    const players = world.getPlayers();
    let found = players.find((player) => player.peerId === peerId);
    if (!found && (peerId === "You" || peerId === "Host" || peerId === "System")) {
        found = players.find((player) => player.isHost);
    }
    return found && found.seat ? found.seat : "@" + peerId;
}
/** Whether someone is at the table in `seat` (a seat, or a seatless person's "@" + id). */
function tblSeatOccupied(seat) {
    return world.getPlayers().some((player) => (seat.charAt(0) === "@" ? "@" + player.peerId === seat : player.seat === seat));
}
/** Give `colour` to `seat` unless the colours are already settled (by the settings or by play). */
function tblClaimColour(seat, colour) {
    if (mtcSeatsLocked)
        return;
    if (tblSettings.blackSeat)
        gameSeatOf[TBL_BLACK] = tblSettings.blackSeat;
    if (tblSettings.whiteSeat)
        gameSeatOf[TBL_WHITE] = tblSettings.whiteSeat;
    if (!seat)
        return;
    const key = tblColourKey(colour);
    const other = tblColourKey(-colour);
    if (gameSeatOf[key] === null && gameSeatOf[other] !== seat)
        gameSeatOf[key] = seat;
    if (gameSeatOf[other] === null && gameSeatOf[key] !== null) {
        const opponent = world.getPlayers().find((player) => player.seat !== null && player.seat !== gameSeatOf[key]);
        if (opponent && opponent.seat)
