        return 1;
    if (seat !== null && gameSeatOf[TBL_WHITE] === seat)
        return -1;
    tblClaimColour(seat, othColourToMove(game));
    if (seat !== null && gameSeatOf[TBL_BLACK] === seat)
        return 1;
    if (seat !== null && gameSeatOf[TBL_WHITE] === seat)
        return -1;
    return 0;
}
function tblPlayerName(colour) {
    const seat = gameSeatOf[tblColourKey(colour)];
    const player = seat ? world.getPlayers().find((entry) => entry.seat === seat) : undefined;
    const name = player && player.displayName ? player.displayName : "";
    return name.length > 0 ? tblColourName(colour) + " (" + name + ")" : tblColourName(colour);
}
// ---------------------------------------------------------------- the match ----------
/** Whether this script started (or picked up) the running match and is recording its moves. */
let mtcRecording = false;
/** Moves applied to `game` and not yet recorded: recorded once the table has settled after them. */
