async function mtcStart() {
    mtcPending = [];
    mtcRecording = false;
    mtcSeatsLocked = false;
    if (typeof match === "undefined")
        return;
    const running = mtcRunning();
    if (running) {
        if (running.ranked) {
            world.log("Othello: a ranked match is still running, so this game is not recorded.");
            return;
        }
        try {
            await match.abort("new game");
        }
        catch (error) {
            world.log("Othello: could not stop the previous match (" + tblDescribe(error) + ").");
        }
    }
    const black = tblSettings.blackSeat;
    const white = tblSettings.whiteSeat;
    const seats = black && white && black !== white && tblSeatOccupied(black) && tblSeatOccupied(white) ? [black, white] : null;
    let info;
    try {
        info = await match.start(seats ? { kernel, seats } : { kernel });
    }
    catch (error) {
        world.log("Othello: this game is not recorded as a match (" + tblDescribe(error) + ").");
        return;
    }
    if (!info || info.status !== "live")
        return;
    if (info.ranked && info.participants.length !== 2) {
        mtcRecording = true;
        mtcStopRecording("othello needs two players");
        return;
    }
    mtcRecording = true;
    mtcLockSeats(info);
}
/** After a reload: carry on with a match that is already running. */
function mtcResume() {
    const info = mtcRunning();
    if (!info || info.status !== "live")
        return;
    mtcRecording = true;
    mtcLockSeats(info);
}
/** Apply one move to the game; it is recorded once the table has caught up (`mtcFlush`). */
function tblApply(move) {
