}
/** Record the moves the table has now applied, in order. */
function mtcFlush() {
    const moves = mtcPending;
    mtcPending = [];
    if (!mtcRecording)
        return;
    for (const move of moves) {
        try {
            match.move(move);
        }
        catch (error) {
            world.log("Othello: the match stopped recording (" + tblDescribe(error) + ").");
            mtcRecording = false;
            return;
        }
    }
}
/** The game is over on the board: end the match with the kernel's result. */
function mtcEnd() {
    if (!game || !mtcRecording)
        return;
    mtcFlush();
    const outcome = kernel.terminal(game);
    const info = mtcRunning();
    if (!outcome || !info || !mtcRecording)
        return;
    mtcRecording = false;
    const blackSeat = gameSeatOf[TBL_BLACK];
    const whiteSeat = gameSeatOf[TBL_WHITE];
    // The platform replays the moves with the match's seats in order, so the first seat must be Black.
    const seats = info.participants.map((participant) => participant.seat);
    if (!blackSeat || !whiteSeat || seats.length !== 2 || seats[0] !== blackSeat || seats[1] !== whiteSeat) {
        match.abort("colours not seated").catch(() => undefined);
        return;
    }
    const counts = tblCounts(game.board);
    const scores = {};
    scores[blackSeat] = counts.black;
    scores[whiteSeat] = counts.white;
    const blackValue = outcome.value[TBL_BLACK];
    const reason = counts.black + counts.white === 64 ? "points" : "no moves";
    const result = blackValue === 0 ? { draw: true } : { winner: blackValue > 0 ? blackSeat : whiteSeat };
    match.end(result, { reason, scores }).catch((error) => {
        world.log("Othello: the match result was not accepted (" + tblDescribe(error) + ").");
    });
}
// ---------------------------------------------------------------- saving and status --
async function tblSave() {
    if (!game)
        return;
    await world.setSavedData(JSON.stringify({
        v: 1,
        board: game.board,
        toPlay: game.toPlay,
        over: gameOver,
        note: tblEndNote,
        black: gameSeatOf[TBL_BLACK],
        white: gameSeatOf[TBL_WHITE]
    }), TBL_SAVE_KEY);
}
async function tblLoadSaved() {
    const raw = await world.getSavedData(TBL_SAVE_KEY);
    if (!raw)
        return false;
    try {
        const data = JSON.parse(raw);
        const cells = data.board;
        if (!Array.isArray(cells) || cells.length !== 64 || cells.some((value) => value !== 0 && value !== 1 && value !== -1))
            return false;
        if (data.toPlay !== TBL_BLACK && data.toPlay !== TBL_WHITE)
            return false;
        game = { board: cells.slice(), toPlay: data.toPlay, seats: [TBL_BLACK, TBL_WHITE] };
        gameOver = data.over === true;
        tblEndNote = gameOver && typeof data.note === "string" ? data.note.slice(0, 120) : "";
        gameSeatOf[TBL_BLACK] = typeof data.black === "string" ? data.black : null;
        gameSeatOf[TBL_WHITE] = typeof data.white === "string" ? data.white : null;
        return true;
    }
    catch (error) {
        return false;
    }
}
function tblCounts(cells) {
    let black = 0;
    let white = 0;
    for (const value of cells) {
        if (value === 1)
            black += 1;
        else if (value === -1)
            white += 1;
    }
    return { black, white };
}
function tblResultLine() {
    if (!game)
        return "";
    const counts = tblCounts(game.board);
    if (counts.black === counts.white)
        return "Draw, " + counts.black + "-" + counts.white + ".";
    const winner = counts.black > counts.white ? 1 : -1;
    const high = Math.max(counts.black, counts.white);
    const low = Math.min(counts.black, counts.white);
    return tblPlayerName(winner) + " wins " + high + "-" + low + ".";
}
function tblRenderStatus() {
    if (!game || !tblSquares)
        return;
    const counts = tblCounts(game.board);
    let second;
    if (gameOver) {
        second = tblEndNote.length > 0 ? tblEndNote : tblResultLine();
    }
    else {
        const colour = othColourToMove(game);
        const moves = kernel.legalMoves(game);
        second = moves.length === 1 && moves[0] === OTH_PASS
            ? tblColourName(colour) + " has no move and must pass"
            : tblColourName(colour) + " to move";
    }
    // Beside the a-file, reading toward the board, clear of the board's frame and disc trays (a label
    // closer in sits inside the tray, whose floor is higher than the squares, and cannot be seen).
    const offset = (4 + tblSettings.labelDistance) * tblSquareSize;
    const position = [
        tblCentre[0] - tblFileAxis[0] * offset,
        tblCentre[1] + 0.01,
        tblCentre[2] - tblFileAxis[1] * offset
    ];
    const yaw = (Math.atan2(-tblFileAxis[0], -tblFileAxis[1]) * 180) / Math.PI;
    world.setTextLabel({
        id: TBL_LABEL_ID,
        text: "Black " + counts.black + "  White " + counts.white + "\n" + second,
        position,
        rotationY: yaw,
