}
// ---------------------------------------------------------------- moves on the table -
/** The spare disc to play: off the board, nearest the square, preferring one already showing `colour`. */
function tblPickSpare(reading, square, colour) {
    let best = null;
    let bestScore = Infinity;
    for (const disc of reading.discs) {
        if (disc.cell >= 0)
            continue;
        const score = tblPlanDistance(disc.handle.position, square.position) + (disc.colour === colour ? 0 : 1000);
        if (score < bestScore) {
            best = disc;
            bestScore = score;
        }
    }
    return best;
}
/** Turn over the discs a placement on `cell` brackets, and record the move. */
function tblFlipBracketed(reading, cell) {
    if (!game)
        return 0;
    const flipped = othFlips(game, cell);
    for (const at of flipped) {
        const disc = reading.byCell[at];
        if (disc)
            disc.handle.flip();
        else
            world.log("Othello: no disc on " + tblSquareName(at) + " to turn over.");
    }
