/** After any move: save, find the end of the game, pass for a stuck human, redraw the status. */
async function tblAfterMove() {
    if (!game)
        return;
    for (let guard = 0; guard < 2 && !kernel.terminal(game); guard += 1) {
        const moves = kernel.legalMoves(game);
        const colour = othColourToMove(game);
        // A person cannot place a "pass", so the script passes for them. A bot passes on its own turn.
        if (!(moves.length === 1 && moves[0] === OTH_PASS) || tblColourIsBot(colour))
            break;
        world.broadcast(tblPlayerName(colour) + " has no legal move and passes.");
        tblApply(OTH_PASS);
        if (world.getTurn().enabled && tblColourIsBot(-colour) && !kernel.terminal(game)) {
            world.broadcast("Press End Turn to let " + tblPlayerName(-colour) + " move again.");
        }
    }
    // The table has settled after these moves: record them (each one is a takeback checkpoint).
    mtcFlush();
    if (kernel.terminal(game) && !gameOver) {
        gameOver = true;
        world.broadcast("Game over. " + tblResultLine());
        mtcEnd();
    }
    await tblSave();
    tblRenderStatus();
}
/** A bot (or the script) places for `colour`. */
async function tblPlay(move, colour) {
    if (!game || !tblSquares)
        return;
    if (move === OTH_PASS) {
        world.broadcast(tblPlayerName(colour) + " has no legal move and passes.");
        tblApply(OTH_PASS);
        await tblAfterMove();
        return;
    }
    const reading = await tblRead();
    const square = tblSquares[move];
    if (reading.byCell[move])
        throw new Error(square.name + " is already taken on the table.");
    const disc = tblPickSpare(reading, square, colour);
    if (!disc)
        throw new Error("There is no spare disc off the board to play.");
    if (disc.colour !== colour)
        disc.handle.flip();
    disc.handle.setPosition([square.position[0], square.position[1] + tblSettings.dropHeight, square.position[2]]);
    const flipped = tblFlipBracketed(reading, move);
    world.broadcast(tblPlayerName(colour) + " plays " + square.name + " and turns over " + flipped + (flipped === 1 ? " disc." : " discs."));
    await world.wait(TBL_SETTLE_SECONDS);
    await tblAfterMove();
