/** Accept what the table shows as the position, keeping the side to move. */
async function tblAdopt(reading, why) {
    if (!game)
        return;
    world.log("Othello: " + why + " Following the table.");
    // The recorded moves no longer reach this position, so an unranked match stops here.
    mtcStopRecording("board edited by hand");
    game = { board: reading.board.slice(), toPlay: game.toPlay, seats: [TBL_BLACK, TBL_WHITE] };
    gameOver = false;
    tblEndNote = "";
    tblIllegalCell = -1;
    await tblAfterMove();
}
/**
 * Compare the table with the game. One new disc on an empty square is a move by the side to
