 * illegal, it is left with a notice. Any other difference is accepted as the new position.
 */
async function tblSync(actor) {
    if (!game || !tblSquares)
        return;
    const reading = await tblRead();
    if (reading.crowded.length > 0) {
        world.log("Othello: more than one disc on " + reading.crowded.map(tblSquareName).join(", ") + "; the first one found counts.");
    }
    const changed = [];
    for (let at = 0; at < 64; at += 1)
        if (reading.board[at] !== game.board[at])
            changed.push(at);
    if (changed.length === 0) {
        tblIllegalCell = -1;
        return;
    }
    const placed = changed.length === 1 && game.board[changed[0]] === 0 ? changed[0] : -1;
    if (placed >= 0 && !gameOver) {
        const colour = othColourToMove(game);
        const square = tblSquares[placed];
        if (tblColourIsBot(colour)) {
            if (tblIllegalCell !== placed)
                world.broadcast("It is " + tblPlayerName(colour) + "'s turn - the disc on " + square.name + " does not count.");
            tblIllegalCell = placed;
            return;
        }
        // Turn order: once the colour to move belongs to someone at the table, only they may place
        // for it. (A colour nobody present holds is open, so one person on a solo table can play
        // both sides, or the side whose configured seat is empty.)
        const mover = gameSeatOf[tblColourKey(colour)];
        if (actor !== null && mover !== null && tblSeatOccupied(mover) && mover !== tblSeatOfPeer(actor)) {
            if (tblIllegalCell !== placed)
                world.broadcast("It is " + tblPlayerName(colour) + "'s move - the disc on " + square.name + " does not count.");
            tblIllegalCell = placed;
            return;
        }
        if (othFlips(game, placed).length === 0) {
            if (tblIllegalCell !== placed) {
                world.broadcast(square.name + " is not a legal move for " + tblColourName(colour) + " - take that disc back.");
            }
            tblIllegalCell = placed;
            return;
        }
        tblIllegalCell = -1;
        if (actor !== null)
            tblClaimColour(tblSeatOfPeer(actor), colour);
        const disc = reading.byCell[placed];
        if (disc && disc.colour !== colour)
            disc.handle.flip();
        const flipped = tblFlipBracketed(reading, placed);
        world.broadcast(tblPlayerName(colour) + " plays " + square.name + " and turns over " + flipped + (flipped === 1 ? " disc." : " discs."));
        await world.wait(TBL_SETTLE_SECONDS);
        await tblAfterMove();
        const next = othColourToMove(game);
        if (!gameOver && world.getTurn().enabled && tblColourIsBot(next)) {
            world.broadcast("Press End Turn to let " + tblPlayerName(next) + " move.");
        }
        return;
    }
    const where = changed.map(tblSquareName).join(", ");
    if (mtcRankedLive()) {
        // Ranked: the rules are enforced, so the board goes back to the game instead.
        world.broadcast("Ranked match: the board was changed by hand (" + where + "), so it is put back.");
        tblLayOut(reading, game.board);
        tblIllegalCell = -1;
        await world.wait(TBL_SETTLE_SECONDS);
        return;
    }
    await tblAdopt(reading, "The board was changed by hand (" + where + ").");
