// ---------------------------------------------------------------- new game -----------
/** A place beside the board for a disc that has no tray spot on record. */
function tblSpillSpot(index) {
    const out = (4 + 1.2) * tblSquareSize;
    const along = ((index % 8) - 3.5) * tblSquareSize;
    return [
        tblCentre[0] + tblFileAxis[0] * out + tblRankAxis[0] * along,
        tblCentre[1] + 0.05 + Math.floor(index / 8) * 0.03,
        tblCentre[2] + tblFileAxis[1] * out + tblRankAxis[1] * along
    ];
}
/**
 * Make the discs on the squares show `board`: discs on squares that should be empty go back
 * where they came from, missing discs come from the trays, and wrong-side-up discs turn over.
 */
function tblLayOut(reading, board) {
    if (!tblSquares)
        return;
    let spill = 0;
    for (let at = 0; at < 64; at += 1) {
        const disc = reading.byCell[at];
        if (disc && board[at] === 0) {
            const home = tblHomes.get(disc.handle.id);
            disc.handle.setPosition(home ? [home[0], home[1] + 0.02, home[2]] : tblSpillSpot(spill++));
            disc.cell = -1;
            reading.byCell[at] = null;
        }
    }
    for (let at = 0; at < 64; at += 1) {
        const want = board[at];
        if (want === 0)
            continue;
        const disc = reading.byCell[at];
        if (disc) {
            if (disc.colour !== want)
                disc.handle.flip();
            continue;
        }
        const square = tblSquares[at];
        const spare = tblPickSpare(reading, square, want);
        if (!spare) {
            world.broadcast("Othello: not enough discs off the board to set up.");
            break;
        }
        if (spare.colour !== want)
            spare.handle.flip();
        spare.handle.setPosition([square.position[0], square.position[1] + tblSettings.dropHeight, square.position[2]]);
        spare.cell = at;
        reading.byCell[at] = spare;
    }
}
async function tblNewGame() {
    if (!tblSquares)
        return;
    const start = kernel.initial([TBL_BLACK, TBL_WHITE]);
    tblLayOut(await tblRead(), start.board);
    game = start;
    gameOver = false;
    tblEndNote = "";
    tblIllegalCell = -1;
    gameSeatOf[TBL_BLACK] = null;
    gameSeatOf[TBL_WHITE] = null;
    await world.wait(TBL_SETTLE_SECONDS);
    await mtcStart();
    if (mtcSeatsLocked) {
        world.broadcast("New Othello game, ranked: " + tblPlayerName(1) + " against " + tblPlayerName(-1) + ".");
    }
    else {
        world.broadcast("New Othello game. Whoever moves first plays Black.");
    }
    await tblAfterMove();
}
// ---------------------------------------------------------------- start up -----------
async function tblEnsureReady() {
    if (tblSquares && game)
        return true;
    if (!tblSquares && !(await tblLoadSquares()))
        return false;
    if (game)
        return true;
    if (await tblLoadSaved()) {
        mtcResume();
        await tblSync(null);
        tblRenderStatus();
        return true;
    }
    const reading = await tblRead();
    const start = kernel.initial([TBL_BLACK, TBL_WHITE]);
    if (tblDiscCount(reading.board) === 0) {
        await tblNewGame();
        return game !== null;
    }
    if (tblBoardsEqual(reading.board, start.board)) {
        game = start;
        gameOver = false;
        if (mtcRunning())
            mtcResume();
        else
            await mtcStart();
    }
    else {
        // A position nobody saved: every move adds one disc, so with no passes Black moves on an even count.
        const toPlay = tblDiscCount(reading.board) % 2 === 0 ? TBL_BLACK : TBL_WHITE;
        game = { board: reading.board.slice(), toPlay, seats: [TBL_BLACK, TBL_WHITE] };
        world.log("Othello: picked up a game in progress; " + toPlay + " to move.");
    }
    gameOver = false;
    await tblAfterMove();
    return true;
}
function botDial(table, difficultyId, fallback) {
    return difficultyId !== null && table[difficultyId] !== undefined ? table[difficultyId] : table[fallback];
}
/**
 * Every bot this script can play, keyed by its HANDLER id. On a table with turns the platform
 * calls the registered `onTurn`; on a table without them (every solo table) it never does, and
 * the script plays a seated bot itself, finding its chooser by the bot's id - so each bot's
 * manifest id is kept equal to its handler.
 */
const BOT_CHOOSERS = {
    greedy: async (state) => othGreedyMove(state),
    minimax: async (state, difficultyId) => othMinimaxMove(state, botDial(BOT_MINIMAX_DEPTH, difficultyId, "normal")),
    // A scripted bot that searches with the kernel's heuristic: `ai.mcts` with no model runs on
    // any device and never calls a model.
    search: async (state, difficultyId, signal) => {
        const result = await ai.mcts({ kernel, state, simulations: botDial(BOT_SEARCH_SIMULATIONS, difficultyId, "normal"), signal });
        return result.move;
    },
    // The model-backed bot. If this host cannot run the model, the search carries on with the
    // kernel's heuristic by itself.
    "othello-ai": async (state, difficultyId, signal) => {
        const level = difficultyId !== null && BOT_AI_LEVELS[difficultyId] !== undefined ? BOT_AI_LEVELS[difficultyId] : BOT_AI_LEVELS["medium"];
        const result = await ai.mcts({
            kernel,
            modelId: level.modelId,
            state,
            simulations: level.simulations,
            temperature: level.temperature,
            signal
        });
        return result.move;
    }
};
/** Pause before a bot the script drives itself moves, so a person can see what happened. */
const BOT_PACE_SECONDS = 0.8;
/**
 * One bot turn: catch up with the table, take a pass that is owed, then choose and play.
 * The table ends the bot's turn when this resolves; a throw makes it skip the turn with a notice.
 */
async function botTakeTurn(ctx, chooser) {
    await tblRun(async () => {
        if (!(await tblEnsureReady()) || !game)
            throw new Error("the board is not set up (see the chat).");
        await tblSync(null);
        if (gameOver)
            return;
        const colour = tblColourOfSeat(ctx.seat);
        if (colour === 0)
            throw new Error("this bot's seat plays neither colour.");
        if (othColourToMove(game) !== colour) {
            const owed = kernel.legalMoves(game);
            if (owed.length === 1 && owed[0] === OTH_PASS) {
                world.broadcast(tblPlayerName(-colour) + " has no legal move and passes.");
                tblApply(OTH_PASS);
            }
            else {
                world.broadcast("Waiting for " + tblPlayerName(-colour) + " to place a disc.");
                return;
            }
        }
        if (kernel.terminal(game)) {
            await tblAfterMove();
            return;
        }
        const move = await chooser(game, ctx.difficultyId, ctx.signal);
        if (ctx.signal.aborted)
            return;
        await tblPlay(move, colour);
    });
}
bots.register({ id: "greedy", onTurn: (ctx) => botTakeTurn(ctx, BOT_CHOOSERS["greedy"]) });
bots.register({ id: "minimax", onTurn: (ctx) => botTakeTurn(ctx, BOT_CHOOSERS["minimax"]) });
bots.register({ id: "search", onTurn: (ctx) => botTakeTurn(ctx, BOT_CHOOSERS["search"]) });
bots.register({ id: "othello-ai", onTurn: (ctx) => botTakeTurn(ctx, BOT_CHOOSERS["othello-ai"]) });
/**
 * With turn mode off (every solo table), nobody calls a bot's `onTurn`, so the script plays
 * its seated bots itself: whenever the colour to move belongs to a bot, that bot moves.
 * Two bots and no person who has moved yet: the first seated bot takes Black and they play
 * each other. One bot: it waits for the person to make the first move, then takes the other
 * colour. Run inside the table queue.
 */
async function botDriveSeatedBots() {
    for (let guard = 0; guard < 140; guard += 1) {
        if (!game || gameOver || world.getTurn().enabled)
            return;
        const seatedBots = world.getPlayers().filter((player) => player.isBot && player.seat !== null);
        if (seatedBots.length === 0)
            return;
        if (gameSeatOf[TBL_BLACK] === null && gameSeatOf[TBL_WHITE] === null && seatedBots.length >= 2) {
            gameSeatOf[TBL_BLACK] = seatedBots[0].seat;
            gameSeatOf[TBL_WHITE] = seatedBots[1].seat;
        }
        const colour = othColourToMove(game);
        const seat = gameSeatOf[tblColourKey(colour)];
        const player = seatedBots.find((entry) => entry.seat === seat);
        if (!player)
            return;
        const chooser = player.botId !== null ? BOT_CHOOSERS[player.botId] : undefined;
        if (!chooser) {
            world.broadcast("Othello: this script has no bot called \"" + String(player.botId) + "\".");
            return;
        }
        await world.wait(BOT_PACE_SECONDS);
        if (!game || gameOver)
            return;
        const moves = kernel.legalMoves(game);
        const move = moves.length === 1 && moves[0] === OTH_PASS ? OTH_PASS : await chooser(game, player.difficultyId, undefined);
        await tblPlay(move, colour);
    }
}
function botKick() {
    void tblRun(async () => {
        if (await tblEnsureReady())
            await botDriveSeatedBots();
    });
}
// ---------------------------------------------------------------- people --------------
globalEvents.onObjectDropped.add((object, context) => {
    if (object.kind !== "token" || context.actor === "Script")
        return;
    void tblRun(async () => {
        if (!(await tblEnsureReady()))
            return;
        await world.wait(TBL_SETTLE_SECONDS);
        await tblSync(context.actor);
        await botDriveSeatedBots();
    });
});
globalEvents.onObjectAction.add((object, action, context) => {
    if (object.kind !== "token" || action !== "flip" || context.actor === "Script")
        return;
    void tblRun(async () => {
        if (!(await tblEnsureReady()))
            return;
        await world.wait(TBL_SETTLE_SECONDS);
        await tblSync(context.actor);
        await botDriveSeatedBots();
    });
});
globalEvents.onPlayerJoined.add(() => botKick());
globalEvents.onSeatChanged.add(() => botKick());
world.addObjectMenuItem({ id: TBL_MENU_NEW_GAME, label: "New Othello game", match: { kinds: ["board"] } });
globalEvents.onObjectMenuItem.add((object, itemId) => {
    if (itemId !== TBL_MENU_NEW_GAME)
        return;
    void tblRun(async () => {
        if (!tblSquares && !(await tblLoadSquares()))
            return;
        if (mtcRankedLive()) {
            world.broadcast("A ranked match is being played: finish it, resign or agree a draw before starting a new game.");
            return;
        }
        await tblNewGame();
        await botDriveSeatedBots();
    });
});
// ---------------------------------------------------------------- match events -------
// A table without the match API (an older host) plays the same game, unrecorded.
if (typeof match !== "undefined") {
    /** A player resigned or left past the grace period: the platform scores it; the board says so. */
    match.onForfeit.add((participant) => {
        void tblRun(async () => {
            const colour = participant.seat === gameSeatOf[TBL_BLACK] ? 1 : participant.seat === gameSeatOf[TBL_WHITE] ? -1 : 0;
            const who = colour !== 0 ? tblPlayerName(colour) : participant.seat;
            world.broadcast(who + " forfeits the match.");
            mtcPending = [];
            mtcRecording = false;
            if (!game || gameOver || colour === 0)
                return;
            gameOver = true;
            tblEndNote = tblColourName(colour) + " forfeits. " + tblColourName(-colour) + " wins.";
            await tblSave();
            tblRenderStatus();
        });
    });
    /** Everyone agreed a draw: the platform records it; the board says so. */
    match.onDrawAgreed.add(() => {
        void tblRun(async () => {
            mtcPending = [];
            mtcRecording = false;
            if (!game || gameOver)
                return;
            gameOver = true;
            tblEndNote = "Draw agreed.";
            world.broadcast("Draw agreed.");
            await tblSave();
            tblRenderStatus();
        });
    });
    /**
     * Every player agreed to take back the last move. The platform has already put the table back;
     * rebuild the game from the moves that still count and redraw the score.
     */
    match.onTakeback.add((info) => {
        void tblRun(async () => {
            if (!tblSquares)
                return;
            mtcPending = [];
            game = replay(kernel, match.moves());
            gameOver = kernel.terminal(game) !== null;
            tblEndNote = "";
            tblIllegalCell = -1;
            world.broadcast("Move taken back (" + info.movesRemaining + " moves stand). " + tblColourName(othColourToMove(game)) + " to move.");
            await tblSave();
            tblRenderStatus();
            await botDriveSeatedBots();
        });
    });
    match.onFinalized.add((info) => {
        world.log("Othello: the match is " + info.status + (info.ranked ? " (ranked)." : " (unranked)."));
    });
}
void tblRun(async () => {
    if (!(await tblEnsureReady()))
        return;
    world.log("Othello ready.");
    await botDriveSeatedBots();
});
